import config
from search.astar import WeightedAStar
from search.heuristics import OctileHeuristic

def _generate_grid(grid_size: int, obstacle_density: float, seed: int) -> set:
    """Generate random obstacles."""
    obstacles = set()
    rng = random.Random(seed)
    for _ in range(int(grid_size**2 * obstacle_density)):
        x = rng.randint(0, grid_size - 1)
        y = rng.randint(0, grid_size - 1)
        obstacles.add((x, y))
    return obstacles

def _dijkstra_baseline(grid_size: int, start: Tuple[int, int], goal: Tuple[int, int], obstacles: set) -> Dict:
    """Baseline Dijkstra/BFS search."""
    # Placeholder for existing baseline logic
    from collections import deque
    visited = {start}
    queue = deque([(start, 0)])
    while queue:
        current, dist = queue.popleft()
        if current == goal:
            return {"expansions": len(visited), "length": dist}
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0: continue
                nx, ny = current[0]+dx, current[1]+dy
                if 0 <= nx < grid_size and 0 <= ny < grid_size and (nx, ny) not in obstacles and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), dist + 1))
    return {"expansions": len(visited), "length": None}

def run_benchmark():
    """Run the benchmark experiment and save results to results.csv."""
    os.makedirs("figures", exist_ok=True)
    results = []
    rng = random.Random(config.SEED)

    for i in range(config.NUM_RUNS):
        grid_seed = config.SEED + i
        obstacles = _generate_grid(config.GRID_SIZE, config.OBSTACLE_DENSITY, grid_seed)
        # Avoid start/goal being obstacles
        if (0, 0) in obstacles: obstacles.discard((0, 0))
        if (config.GRID_SIZE-1, config.GRID_SIZE-1) in obstacles: obstacles.discard((config.GRID_SIZE-1, config.GRID_SIZE-1))

        start = (0, 0)
        goal = (config.GRID_SIZE - 1, config.GRID_SIZE - 1)

        # Dijkstra Baseline
        dijkstra_res = _dijkstra_baseline(config.GRID_SIZE, start, goal, obstacles)
        baseline_len = dijkstra_res["length"]
        baseline_exp = dijkstra_res["expansions"]

        # Weighted A*
        h = OctileHeuristic(config.GRID_SIZE, start, goal)
        astar = WeightedAStar(h.heuristic, config.ASTAR_WEIGHT, config.GRID_SIZE)
        astar_res = astar.search(start, goal, obstacles)

        if astar_res["path"] is not None:
            # Calculate actual path length (Manhattan/Steps) for optimality gap
            # Assuming uniform cost 1 per step for simplicity in gap calc
            path_len = len(astar_res["path"]) - 1 
            optimality_gap = 0 if baseline_len is not None and baseline_len > 0 else abs(path_len - baseline_len) / baseline_len
            # Simple gap: |A* length - Optimal| / Optimal
            if baseline_len:
                gap_val = abs(path_len - baseline_len) / baseline_len
            else:
                gap_val = 1.0 # No path found in baseline implies worst case
        else:
            path_len = None
            gap_val = 1.0

        results.append({
            "method": "weighted_astar",
            config.METRIC_EXPANSIONS: astar_res["expansions"],
            config.METRIC_OPTIMALITY_GAP: gap_val,
            "baseline_expansions": baseline_exp
        })

    with open("results.csv", "w", newline="") as f:
        if results:
            writer = csv.DictWriter(f, fieldnames=results[0].keys())
            writer.writeheader()
            writer.writerows(results)

    return results",
