def run_experiment():
    """Run the benchmark experiment and save results to results.csv."""
    os.makedirs("figures", exist_ok=True)
    results = []
    rng = random.Random(config.SEED)

    for i in range(config.NUM_RUNS):
        grid_seed = config.SEED + i
        obstacles = set()
        # Generate obstacles deterministically
        obs_rng = random.Random(grid_seed)
        for _ in range(int(config.GRID_SIZE**2 * config.OBSTACLE_DENSITY)):
            x = obs_rng.randint(0, config.GRID_SIZE - 1)
            y = obs_rng.randint(0, config.GRID_SIZE - 1)
            obstacles.add((x, y))

        # Avoid start/goal being obstacles
        if (0, 0) in obstacles: obstacles.discard((0, 0))
        if (config.GRID_SIZE-1, config.GRID_SIZE-1) in obstacles: obstacles.discard((config.GRID_SIZE-1, config.GRID_SIZE-1))

        start = (0, 0)
        goal = (config.GRID_SIZE - 1, config.GRID_SIZE - 1)

        # Existing Baseline Dijkstra
        dijkstra_res = dijkstra_search(config.GRID_SIZE, start, goal, obstacles)
        baseline_len = dijkstra_res.get("length")
        baseline_exp = dijkstra_res.get("expansions", 0)

        # Weighted A*
        h = OctileHeuristic(config.GRID_SIZE, start, goal)
        astar = WeightedAStar(h.heuristic, config.ASTAR_WEIGHT, config.GRID_SIZE)
        astar_res = astar.search(start, goal, obstacles)

        # Calculate metrics
        if astar_res["path"] is not None and baseline_len is not None:
            path_len = len(astar_res["path"]) - 1 
            optimality_gap = abs(path_len - baseline_len) / baseline_len if baseline_len > 0 else 0.0
        else:
            path_len = astar_res.get("length")
            optimality_gap = 1.0 # Worst case if no path or baseline failed

        results.append({
            "method": "weighted_astar",
            config.METRIC_EXPANSIONS: astar_res["expansions"],
            config.METRIC_OPTIMALITY_GAP: optimality_gap,
            "baseline_expansions": baseline_exp
        })

    with open("results.csv", "w", newline="") as f:
        if results:
            writer = csv.DictWriter(f, fieldnames=results[0].keys())
            writer.writeheader()
            writer.writerows(results)

