from typing import List, Tuple, Dict, Any, Set

class WeightedAStar:
    """Implements weighted A* search with f(n) = g(n) + w*h(n)."""

    def __init__(self, heuristic_function: callable, weight: float, grid_size: int) -> None:
        """Initialize with a heuristic function, weight factor, and grid size."""
        self.heuristic_func = heuristic_function
        self.weight = weight
        self.grid_size = grid_size

    def search(self, start: Tuple[int, int], goal: Tuple[int, int], obstacles: Set[Tuple[int, int]]) -> Dict[str, Any]:
        """Run A* search. Returns dict with 'path' (list of nodes), 'expansions' (int).

        >>> from search.heuristics import OctileHeuristic
        >>> h = OctileHeuristic(10, (0, 0), (5, 5))
        >>> astar = WeightedAStar(h.heuristic, 1.5, 10)
        >>> result = astar.search((0, 0), (5, 5), set())
        >>> 'path' in result and 'expansions' in result
        True
        """
        if start == goal:
            return {"path": [start], "expansions": 0}

        open_set = [(0, start)]
        came_from = {}
        g_score = {start: 0}
        expansions = 0

        while open_set:
            _, current = heapq.heappop(open_set)
            expansions += 1

            if current == goal:
                path = []
                while current in came_from:
                    path.append(current)
                    current = came_from[current]
                path.append(start)
                return {"path": path[::-1], "expansions": expansions}

            for neighbor in self._get_neighbors(current, obstacles):
                tentative_g = g_score[current] + 1 # Uniform cost
                if neighbor not in g_score or tentative_g < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g
                    f_score = tentative_g + self.weight * self.heuristic_func(neighbor)
                    heapq.heappush(open_set, (f_score, neighbor))

        return {"path": None, "expansions": expansions}

    def _get_neighbors(self, node: Tuple[int, int], obstacles: Set[Tuple[int, int]]) -> List[Tuple[int, int]]:
        """Get 8-connected neighbors within grid bounds and avoiding obstacles."""
        x, y = node
        neighbors = []
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if 0 <= nx < self.grid_size and 0 <= ny < self.grid_size:
                    if (nx, ny) not in obstacles:
                        neighbors.append((nx, ny))
        return neighbors

